t = int(input())
for _ in range(t):
	(n, k) = map(int, input().split())
	ans = []
	if n % 2 == 0:
		bo = ''
		c = bin(k)[2:]
		for i in c:
			if i == '0':
				bo += '1'
			else:
				bo += '0'
		d = int(bo, 2)
		for i in range(n - 2):
			ans.append(k)
		if d == 0:
			k1 = '1' + '0' * (len(c) - 1)
			k2 = '0' + '1' * (len(c) - 1)
			ans.append(int(k1, 2))
			ans.append(int(k2, 2))
		else:
			ans.append(d)
			ans.append(k)
	else:
		bo = ''
		c = bin(k)[2:]
		for i in c:
			if i == '0':
				bo += '1'
			else:
				bo += '0'
		d = int(bo, 2)
		if d == 0:
			ans.append(k)
			ans.append(k)
			ans.append(k)
		else:
			fa = ''
			for i in range(1, len(c)):
				if c[i] == '1':
					fa += '1'
				else:
					fa += '0'
			k2 = '0' + '1' * (len(c) - 1)
			ans.append(k)
			if int(fa, 2) != 0:
				ans.append(int(fa, 2))
				ans.append(int(k2, 2))
			else:
				k2 = '0' + '1' * (len(c) - 2) + '0'
				ans.append(int(k2, 2))
				ans.append(1)
		for i in range(n - 3):
			ans.append(k)
	if n == 1:
		ans = [k]
	elif n % 2 != 0 and k == 2:
		ans = [k] * n
	elif n % 2 == 0 and k == 1:
		ans = [1] * n
	print(*ans)
